* { box-sizing: border-box; }

.app {
  min-height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  border-radius: var(--appsmith-theme-borderRadius);
  box-shadow: var(--appsmith-theme-boxShadow);
  padding: 20px 22px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, system-ui, sans-serif;
  background: #ffffff;
  color: #1b1f27;
  font-size: 13px;
}

.header { margin-bottom: 14px; }
.header h1 { font-size: 18px; font-weight: 700; margin: 0 0 2px; letter-spacing: -0.01em; }
.header .sub { color: #6b7280; font-size: 12px; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid #e6e8ec; margin-bottom: 16px; }
.tab {
  padding: 8px 14px; cursor: pointer; font-weight: 600; font-size: 13px;
  color: #6b7280; border-bottom: 2px solid transparent; margin-bottom: -1px; user-select: none;
}
.tab:hover { color: #1b1f27; }
.tab.active { color: var(--appsmith-theme-primaryColor, #6229e6); border-bottom-color: var(--appsmith-theme-primaryColor, #6229e6); }

/* KPI cards */
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 16px; }
.kpi { border: 1px solid #e6e8ec; border-radius: 10px; padding: 12px 14px; background: #fbfbfd; }
.kpi .k-label { font-size: 11px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600; display:flex; align-items:center; gap:6px; }
.kpi .k-value { font-size: 24px; font-weight: 700; margin-top: 4px; line-height: 1.1; }
.kpi .k-sub { font-size: 11px; color: #8a94a6; margin-top: 2px; }
.kpi.total { background: #f3f0ff; border-color: #e2d9ff; }
.dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }

/* Controls */
.controls { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px; flex-wrap: wrap; }
.seg-toggle { display: inline-flex; background: #f1f2f5; border-radius: 8px; padding: 3px; }
.seg-toggle button {
  border: none; background: none; padding: 6px 12px; border-radius: 6px; cursor: pointer;
  font-weight: 600; font-size: 12px; color: #6b7280;
}
.seg-toggle button.active { background: #fff; color: #1b1f27; box-shadow: 0 1px 2px rgba(0,0,0,0.08); }
.search { position: relative; }
.search input {
  border: 1px solid #e0e2e8; border-radius: 8px; padding: 7px 10px 7px 30px; font-size: 12px;
  width: 240px; outline: none; background: #fff;
}
.search input:focus { border-color: var(--appsmith-theme-primaryColor, #6229e6); }
.search .ico { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: #9aa0ac; font-size: 13px; }

/* Table / tree */
.tree { border: 1px solid #e6e8ec; border-radius: 10px; overflow: hidden; }
.thead, .row { display: grid; grid-template-columns: minmax(240px, 2.4fr) 78px 1fr 68px; align-items: center; }
.thead {
  background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase;
  letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; padding: 9px 14px;
}
.thead .num, .row .num { text-align: right; }
.row { padding: 8px 14px; border-bottom: 1px solid #f0f1f4; cursor: default; }
.row:last-child { border-bottom: none; }
.row.clickable { cursor: pointer; }
.row.clickable:hover { background: #fafbfc; }
.row.lvl0 { font-weight: 650; }
.row.lvl1 { background: #fcfcfd; }
.row.lvl2 { background: #fafbfc; }
.row.leaf { background: #f7f8fa; }
.name-cell { display: flex; align-items: center; gap: 7px; min-width: 0; }
.caret { width: 14px; text-align: center; color: #9aa0ac; font-size: 10px; transition: transform 0.12s; flex: none; }
.caret.open { transform: rotate(90deg); }
.name-txt { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.count-big { font-variant-numeric: tabular-nums; font-weight: 600; }
.mig-pct { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }

/* stacked bar */
.bar { display: flex; height: 8px; width: 120px; flex: none; border-radius: 4px; overflow: hidden; background: #eef0f3; }
.bar span { display: block; height: 100%; }
.bar-wrap { display: flex; align-items: center; gap: 10px; }
.bar-legend { font-size: 11px; color: #8a94a6; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* account leaf badges */
.acct { display: flex; align-items: center; gap: 8px; padding: 5px 14px 5px 44px; border-bottom: 1px solid #f0f1f4; font-size: 12px; }
.acct:last-child { border-bottom: none; }
.badge { font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 20px; color: #fff; white-space: nowrap; }

/* opportunity leaf rows */
.opp-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 12px; padding: 7px 14px; border-bottom: 1px solid #f0f1f4; }
.opp-row:last-child { border-bottom: none; }
.opp-row:hover { background: #fafbfc; }
.opp-left { display: flex; align-items: flex-start; gap: 8px; min-width: 0; }
.opp-txt { min-width: 0; }
.opp-acct { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-meta { font-size: 11px; color: #8a94a6; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-amt { font-variant-numeric: tabular-nums; font-weight: 600; font-size: 12.5px; white-space: nowrap; }
.opp-row .badge { margin-top: 1px; }

/* empty / placeholder */
.empty, .placeholder { text-align: center; padding: 40px 24px; color: #6b7280; }
.empty h3, .placeholder h3 { color: #1b1f27; font-size: 15px; margin: 0 0 8px; }
.empty code { background: #f1f2f5; padding: 1px 6px; border-radius: 4px; font-size: 12px; }
.empty ol { text-align: left; max-width: 460px; margin: 14px auto 0; line-height: 1.7; font-size: 12px; }
.pill { display:inline-block; background:#f3f0ff; color:#6229e6; border-radius:20px; padding:3px 10px; font-size:11px; font-weight:600; margin-bottom:10px; }

