/**
 * FULL FLEX – Commercial Offering Migration Dashboard (Appsmith Custom Widget)
 * Vanilla JS (no build step). Two tabs:
 *   Account View     – appsmith.model.accounts (AccountMigration query)
 *   Opportunity View – appsmith.model.opps    (OppMigration1 + OppMigration2)
 *
 * Both model values are expected to be arrays of Salesforce records (the
 * Default Model unwraps the REST {status,headers,output.records} envelope);
 * the widget also unwraps defensively as a fallback.
 */

var SEGMENTS = [
  { key: "migrated",    label: "Migriert",     color: "#1f9d55" },
  { key: "inMigration", label: "In Migration", color: "#e0a800" },
  { key: "open",        label: "Noch offen",   color: "#8a94a6" }
];
var SEG_BY_KEY = {};
SEGMENTS.forEach(function (s) { SEG_BY_KEY[s.key] = s; });

var BUCKETS = [
  { key: "b30",  label: "Läuft aus in ≤ 30 Tagen", max: 30 },
  { key: "b90",  label: "31 – 90 Tage",            max: 90 },
  { key: "b180", label: "91 – 180 Tage",           max: 180 },
  { key: "b365", label: "181 – 365 Tage",          max: 365 },
  { key: "bmax", label: "> 365 Tage",              max: Infinity }
];

var state = {
  tab: "account",
  accGroupBy: "motion",   // motion | tl
  oppGroupBy: "timeline", // timeline | motion | tl
  search: "",
  expanded: {}
};

/* ---------- generic helpers ---------- */

function el(tag, cls, html) {
  var e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
  });
}
function pct(n, d) { return d ? Math.round((n / d) * 100) : 0; }

function looksLikeRecords(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return false;
  var f = arr[0];
  return !!(f && typeof f === "object" && (f.attributes || f.Id || f.Name));
}
function findRecords(x, depth) {
  if (x == null || depth > 6) return null;
  if (looksLikeRecords(x)) return x;
  if (Array.isArray(x)) return null;
  if (typeof x === "object") {
    if (looksLikeRecords(x.records)) return x.records;
    for (var k in x) {
      if (!Object.prototype.hasOwnProperty.call(x, k)) continue;
      var r = findRecords(x[k], depth + 1);
      if (r) return r;
    }
  }
  return null;
}
function modelArray(key) {
  var m = (window.appsmith && appsmith.model) || {};
  var v = m[key];
  if (Array.isArray(v)) return v;
  return findRecords(v, 0) || [];
}

var fmtEur = (function () {
  try {
    var f = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });
    return function (n) { return f.format(n || 0); };
  } catch (e) {
    return function (n) { return "€" + Math.round(n || 0); };
  }
})();
function fmtDate(s) {
  if (!s) return "–";
  var d = new Date(s);
  if (isNaN(d)) return esc(s);
  var p = function (x) { return (x < 10 ? "0" : "") + x; };
  return p(d.getDate()) + "." + p(d.getMonth() + 1) + "." + d.getFullYear();
}
function daysUntil(s) {
  var d = new Date(s);
  if (isNaN(d)) return Infinity;
  return Math.floor((d - new Date()) / 86400000);
}

/* ---------- counts ---------- */

function emptyCounts() { return { migrated: 0, inMigration: 0, open: 0, total: 0, amount: 0 }; }
function addTo(c, seg, amount) { c[seg] += 1; c.total += 1; c.amount += (amount || 0); }

function stackedBar(counts) {
  var bar = el("div", "bar");
  SEGMENTS.forEach(function (s) {
    var w = counts.total ? (counts[s.key] / counts.total) * 100 : 0;
    if (w > 0) {
      var span = el("span");
      span.style.width = w + "%";
      span.style.background = s.color;
      span.title = s.label + ": " + counts[s.key];
      bar.appendChild(span);
    }
  });
  return bar;
}
function segLegend(counts) {
  return SEGMENTS.map(function (s) {
    return '<span style="color:' + s.color + '">●</span> ' + counts[s.key];
  }).join("&nbsp;&nbsp;");
}
function kpiCard(labelHtml, value, sub, cls) {
  var c = el("div", "kpi" + (cls ? " " + cls : ""));
  c.appendChild(el("div", "k-label", labelHtml));
  c.appendChild(el("div", "k-value", value));
  if (sub) c.appendChild(el("div", "k-sub", sub));
  return c;
}
function segToggle(options, current, onPick) {
  var wrap = el("div", "seg-toggle");
  options.forEach(function (o) {
    var b = el("button", current === o[0] ? "active" : "", o[1]);
    b.addEventListener("click", function () { if (current !== o[0]) onPick(o[0]); });
    wrap.appendChild(b);
  });
  return wrap;
}
function searchBox(placeholder) {
  var search = el("div", "search");
  search.appendChild(el("span", "ico", "🔍"));
  var input = el("input");
  input.type = "text";
  input.placeholder = placeholder;
  input.value = state.search;
  input.addEventListener("input", function (e) { state.search = e.target.value; rerenderBody(); });
  search.appendChild(input);
  return search;
}

/* ---------- data model ---------- */

var NONE_MOTION = "— ohne Motion", NONE_TL = "— ohne Team Lead", NONE_IC = "— ohne Owner";

function acctFields(r) {
  return {
    motion: r.GTM_Motion_Account__c || NONE_MOTION,
    tl: r.Account_Owner_s_Manager__c || NONE_TL,
    ic: r.Account_Owner__c || (r.Owner && r.Owner.Name) || NONE_IC
  };
}
function oppList(r) {
  var o = r.Opportunities;
  if (!o) return [];
  if (Array.isArray(o)) return o;
  if (Array.isArray(o.records)) return o.records;
  return [];
}
function normalizeAccount(r) {
  var a = acctFields(r);
  a.name = r.Name || "(ohne Name)";
  a.segment = r.New_Commercial_Offering__c === true ? "migrated"
    : (oppList(r).some(function (o) { return o && o.Hire_2_0__c === true; }) ? "inMigration" : "open");
  return a;
}
function normalizeOpp(o) {
  var acc = o.Account || {};
  var migrated = acc.New_Commercial_Offering__c === true;
  var potential = o.Hire_2_0__c === true;
  return {
    account: acc.Name || "(ohne Account)",
    name: o.Name || "(ohne Name)",
    motion: acc.GTM_Motion_Account__c || NONE_MOTION,
    tl: acc.Account_Owner_s_Manager__c || NONE_TL,
    ic: acc.Account_Owner__c || NONE_IC,
    end: o.Contract_End_Date__c,
    days: daysUntil(o.Contract_End_Date__c),
    type: o.Contract_type__c,
    stage: o.StageName,
    amount: o.Amount || 0,
    reach: o.Monthly_Reach_Budget__c,
    product: o.Product_Type__c,
    activity: o.LastActivityDate,
    segment: migrated ? "migrated" : (potential ? "inMigration" : "open")
  };
}
function matches(rec, q, fields) {
  if (!q) return true;
  q = q.toLowerCase();
  return fields.map(function (f) { return rec[f] || ""; }).join(" ").toLowerCase().indexOf(q) !== -1;
}

/* ---------- generic grouping tree ---------- */

function buildTree(items, keys, getAmount) {
  var root = { counts: emptyCounts(), children: {}, _order: [] };
  items.forEach(function (it) {
    addTo(root.counts, it.segment, getAmount(it));
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = it[keys[i]];
      if (!node.children[k]) { node.children[k] = { label: k, counts: emptyCounts(), children: {}, _order: [], items: [] }; node._order.push(k); }
      node = node.children[k];
      addTo(node.counts, it.segment, getAmount(it));
      if (i === keys.length - 1) node.items.push(it);
    }
  });
  return root;
}
function sortedChildren(node) {
  return node._order.map(function (k) { return node.children[k]; }).sort(function (a, b) {
    if (b.counts.total !== a.counts.total) return b.counts.total - a.counts.total;
    return String(a.label).localeCompare(String(b.label));
  });
}

function groupRow(label, level, path, counts, hasChildren, showAmount) {
  var open = !!state.expanded[path];
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var nameCell = el("div", "name-cell");
  nameCell.style.paddingLeft = (level * 18) + "px";
  nameCell.appendChild(el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : ""));
  nameCell.appendChild(el("span", "name-txt", esc(label)));
  row.appendChild(nameCell);
  row.appendChild(el("div", "num count-big", String(counts.total)));
  var barCell = el("div", "");
  var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(counts));
  bw.appendChild(el("div", "bar-legend", segLegend(counts)));
  barCell.appendChild(bw);
  row.appendChild(barCell);
  row.appendChild(el("div", "mig-pct", showAmount ? fmtEur(counts.amount) : (pct(counts.migrated, counts.total) + "%")));
  if (hasChildren) row.addEventListener("click", function () { state.expanded[path] = !state.expanded[path]; render(); });
  return row;
}

/* ---------- Account View ---------- */

function currentAccounts() { return modelArray("accounts").map(normalizeAccount); }

function renderAccountView(container, accounts) {
  var total = accounts.length, counts = emptyCounts();
  accounts.forEach(function (a) { addTo(counts, a.segment, 0); });

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Accounts (aktiver Vertrag)", String(total), pct(counts.migrated, total) + "% migriert", "total"));
  SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], total) + "% aller Accounts"));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle([["motion", "Nach Motion"], ["tl", "Nach Team Lead"]], state.accGroupBy,
    function (v) { state.accGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, IC, TL oder Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderAccountBody(body, accounts);
}
function renderAccountBody(body, accounts) {
  body.innerHTML = "";
  var filtered = accounts.filter(function (a) { return matches(a, state.search, ["name", "motion", "tl", "ic"]); });
  var keys = state.accGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
  var leafLevel = keys.length - 1;
  var tree = buildTree(filtered, keys, function () { return 0; });

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  head.appendChild(el("div", "", state.accGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC"));
  head.appendChild(el("div", "num", "Accounts"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Migr. %"));
  treeEl.appendChild(head);

  if (!filtered.length) {
    treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  } else {
    renderAcctNodes(treeEl, tree, 0, "acc", 0 === leafLevel);
  }
  body.appendChild(treeEl);
}
function renderAcctNodes(container, node, level, path, isLeafLevel) {
  sortedChildren(node).forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = isLeafLevel ? child.items.length > 0 : child._order.length > 0;
    container.appendChild(groupRow(child.label, level, childPath, child.counts, hasChildren, false));
    if (state.expanded[childPath]) {
      if (isLeafLevel) {
        child.items.slice().sort(function (a, b) { return a.name.localeCompare(b.name); }).forEach(function (a) {
          var seg = SEG_BY_KEY[a.segment];
          var acct = el("div", "acct");
          acct.style.paddingLeft = ((level + 1) * 18 + 26) + "px";
          var badge = el("span", "badge", seg.label); badge.style.background = seg.color;
          acct.appendChild(badge);
          acct.appendChild(el("span", "name-txt", esc(a.name)));
          container.appendChild(acct);
        });
      } else {
        renderAcctNodes(container, child, level + 1, childPath, level + 1 === (state.accGroupBy === "motion" ? 2 : 1));
      }
    }
  });
}

/* ---------- Opportunity View ---------- */

function currentOpps() { return modelArray("opps").map(normalizeOpp); }

function renderOpportunityView(container, opps) {
  if (opps.length === 0) {
    var empty = el("div", "empty");
    empty.innerHTML =
      "<h3>Noch keine Opportunity-Daten verbunden</h3>" +
      "<p>Erwartet <code>appsmith.model.opps</code> aus <code>OppMigration1</code> + <code>OppMigration2</code> " +
      "(aktive Verträge auf Opportunity-Ebene). SOQL + Default Model siehe Setup-Hinweis.</p>";
    container.appendChild(empty);
    return;
  }
  var total = opps.length, counts = emptyCounts();
  opps.forEach(function (o) { addTo(counts, o.segment, o.amount); });

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Opportunities (aktiver Vertrag)", String(total), "Σ " + fmtEur(counts.amount), "total"));
  SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], total) + "% · " + fmtEur(counts[s.key + "Amt"] || sumAmt(opps, s.key))));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle(
    [["timeline", "Nach Restlaufzeit"], ["motion", "Nach Motion"], ["tl", "Nach Team Lead"]],
    state.oppGroupBy, function (v) { state.oppGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, Opportunity, IC, TL, Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderOppBody(body, opps);
}
function sumAmt(opps, seg) {
  var s = 0; opps.forEach(function (o) { if (o.segment === seg) s += o.amount; }); return s;
}
function renderOppBody(body, opps) {
  body.innerHTML = "";
  var filtered = opps.filter(function (o) { return matches(o, state.search, ["account", "name", "motion", "tl", "ic", "stage"]); });

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  var firstCol = state.oppGroupBy === "timeline" ? "Restlaufzeit / Opportunity"
    : (state.oppGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC");
  head.appendChild(el("div", "", firstCol));
  head.appendChild(el("div", "num", "Opps"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Σ Amount"));
  treeEl.appendChild(head);

  if (!filtered.length) {
    treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  } else if (state.oppGroupBy === "timeline") {
    renderOppTimeline(treeEl, filtered);
  } else {
    var keys = state.oppGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
    var tree = buildTree(filtered, keys, function (o) { return o.amount; });
    renderOppNodes(treeEl, tree, 0, "opp", keys.length - 1);
  }
  body.appendChild(treeEl);
}
function renderOppTimeline(container, opps) {
  var groups = BUCKETS.map(function (b) { return { bucket: b, counts: emptyCounts(), items: [] }; });
  opps.forEach(function (o) {
    for (var i = 0; i < BUCKETS.length; i++) {
      if (o.days <= BUCKETS[i].max) { addTo(groups[i].counts, o.segment, o.amount); groups[i].items.push(o); break; }
    }
  });
