  var controls = el("div", "controls");
  controls.appendChild(segToggle([["motion", "Nach Motion"], ["tl", "Nach Team Lead"]], state.accGroupBy,
    function (v) { state.accGroupBy = v; state.expanded = {}; render(); }));
