/* ---------- Opportunity View ---------- */

function currentOpps() { return modelArray("opps").map(normalizeOpp); }

function renderOpportunityView(container, opps) {
  if (opps.length === 0) {
    var empty = el("div", "empty");
    empty.innerHTML =
      "<h3>Noch keine Opportunity-Daten verbunden</h3>" +
      "<p>Erwartet <code>appsmith.model.opps</code> aus <code>OppMigration1</code> + <code>OppMigration2</code> " +
      "(aktive Verträge auf Opportunity-Ebene). SOQL + Default Model siehe Setup-Hinweis.</p>";
    container.appendChild(empty);
    return;
  }
  var total = opps.length, counts = emptyCounts();
  opps.forEach(function (o) { addTo(counts, o.segment, o.amount); });

  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Opportunities (aktiver Vertrag)", String(total), "Σ " + fmtEur(counts.amount), "total"));
  SEGMENTS.forEach(function (s) {
    kpis.appendChild(kpiCard('<span class="dot" style="background:' + s.color + '"></span>' + s.label,
      String(counts[s.key]), pct(counts[s.key], total) + "% · " + fmtEur(counts[s.key + "Amt"] || sumAmt(opps, s.key))));
  });
  container.appendChild(kpis);

  var controls = el("div", "controls");
  controls.appendChild(segToggle(
    [["timeline", "Nach Restlaufzeit"], ["motion", "Nach Motion"], ["tl", "Nach Team Lead"]],
    state.oppGroupBy, function (v) { state.oppGroupBy = v; state.expanded = {}; render(); }));
  controls.appendChild(searchBox("Account, Opportunity, IC, TL, Motion suchen…"));
  container.appendChild(controls);

  var body = el("div"); body.id = "view-body"; container.appendChild(body);
  renderOppBody(body, opps);
}
function sumAmt(opps, seg) {
  var s = 0; opps.forEach(function (o) { if (o.segment === seg) s += o.amount; }); return s;
}
function renderOppBody(body, opps) {
  body.innerHTML = "";
  var filtered = opps.filter(function (o) { return matches(o, state.search, ["account", "name", "motion", "tl", "ic", "stage"]); });

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  var firstCol = state.oppGroupBy === "timeline" ? "Restlaufzeit / Opportunity"
    : (state.oppGroupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC");
  head.appendChild(el("div", "", firstCol));
  head.appendChild(el("div", "num", "Opps"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Σ Amount"));
  treeEl.appendChild(head);

  if (!filtered.length) {
    treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer</div>'));
  } else if (state.oppGroupBy === "timeline") {
    renderOppTimeline(treeEl, filtered);
  } else {
    var keys = state.oppGroupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
    var tree = buildTree(filtered, keys, function (o) { return o.amount; });
    renderOppNodes(treeEl, tree, 0, "opp", keys.length - 1);
  }
  body.appendChild(treeEl);
}
function renderOppTimeline(container, opps) {
  var groups = BUCKETS.map(function (b) { return { bucket: b, counts: emptyCounts(), items: [] }; });
  opps.forEach(function (o) {
    for (var i = 0; i < BUCKETS.length; i++) {
      if (o.days <= BUCKETS[i].max) { addTo(groups[i].counts, o.segment, o.amount); groups[i].items.push(o); break; }
    }
  });
  groups.forEach(function (g) {
    if (g.items.length === 0) return;
    var path = "opp-tl/" + g.bucket.key;
    container.appendChild(groupRow(g.bucket.label, 0, path, g.counts, true, true));
    if (state.expanded[path]) {
      g.items.slice().sort(function (a, b) { return (a.days - b.days) || (b.amount - a.amount); })
        .forEach(function (o) { container.appendChild(oppRow(o, 1)); });
    }
  });
}
function renderOppNodes(container, node, level, path, leafLevel) {
  sortedChildren(node).forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = level === leafLevel ? child.items.length > 0 : child._order.length > 0;
    container.appendChild(groupRow(child.label, level, childPath, child.counts, hasChildren, true));
    if (state.expanded[childPath]) {
      if (level === leafLevel) {
        child.items.slice().sort(function (a, b) { return (a.days - b.days) || (b.amount - a.amount); })
          .forEach(function (o) { container.appendChild(oppRow(o, level + 1)); });
      } else {
        renderOppNodes(container, child, level + 1, childPath, leafLevel);
      }
    }
  });
}
function oppRow(o, level) {
  var seg = SEG_BY_KEY[o.segment];
  var row = el("div", "opp-row");
  row.style.paddingLeft = (level * 18 + 26) + "px";
  var badge = el("span", "badge", seg.label); badge.style.background = seg.color;
  var left = el("div", "opp-left");
  left.appendChild(badge);
  var txt = el("div", "opp-txt");
  txt.appendChild(el("div", "opp-acct", esc(o.account)));
  var metaBits = [];
  metaBits.push("endet " + fmtDate(o.end) + (isFinite(o.days) ? " (" + o.days + " T)" : ""));
  if (o.type) metaBits.push(esc(o.type));
  if (o.product) metaBits.push(esc(o.product));
  if (o.stage) metaBits.push(esc(o.stage));
  if (o.reach) metaBits.push("REACH " + fmtEur(o.reach) + "/M");
  if (o.activity) metaBits.push("letzte Akt. " + fmtDate(o.activity));
  txt.appendChild(el("div", "opp-meta", esc(o.name) + " · " + metaBits.join(" · ")));
  left.appendChild(txt);
  row.appendChild(left);
  row.appendChild(el("div", "opp-amt", fmtEur(o.amount)));
  return row;
}

/* ---------- shell ---------- */

function rerenderBody() {
  var body = document.getElementById("view-body");
  if (!body) return;
  if (state.tab === "account") renderAccountBody(body, currentAccounts());
  else renderOppBody(body, currentOpps());
}

function render() {
  var root = document.getElementById("root");
  if (!root) return;
  root.innerHTML = "";
  var app = el("div", "app");

  var header = el("div", "header");
  header.appendChild(el("h1", "", "FULL FLEX · Commercial Offering Migration"));
  header.appendChild(el("div", "sub", "Migrationsstatus über aktive Verträge – Account- und Opportunity-Ebene"));
  app.appendChild(header);

  var tabs = el("div", "tabs");
  [["account", "Account View"], ["opportunity", "Opportunity View"]].forEach(function (t) {
    var tab = el("div", "tab" + (state.tab === t[0] ? " active" : ""), t[1]);
    tab.addEventListener("click", function () { state.tab = t[0]; state.search = ""; render(); });
    tabs.appendChild(tab);
  });
  app.appendChild(tabs);

  if (state.tab === "account") {
    var accounts = currentAccounts();
    if (accounts.length === 0) {
      var e = el("div", "empty");
      e.innerHTML = "<h3>Noch keine Daten verbunden</h3><p>Erwartet <code>appsmith.model.accounts</code> aus der Query <code>AccountMigration</code>.</p>";
      app.appendChild(e);
    } else {
      renderAccountView(app, accounts);
    }
  } else {
    renderOpportunityView(app, currentOpps());
  }
  root.appendChild(app);
}

if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(function () { render(); });
  if (appsmith.onModelChange) appsmith.onModelChange(function () { render(); });
} else {
  render();
}
